function maximumSwap(num) {
  const text = String(num);
  let best = num;
  for (let a = 0; a < text.length; a++)
    for (let b = a + 1; b < text.length; b++) {
      const chars = text.split('');
      const keep = chars[a];
      chars[a] = chars[b];
      chars[b] = keep;
      best = Math.max(best, parseInt(chars.join(''), 10));
    }
  return best;
}

