function generate(rand, size) {
  if (size === 'large') {
    if (rand() < 0.1) return [100000000];
    return [10000000 + Math.floor(rand() * 90000000)];
  }
  const roll = rand();
  if (roll < 0.05) return [0];
  if (roll < 0.1) return [100000000];
  const length = 1 + Math.floor(rand() * 7);
  const pool = Array.from({ length: 1 + Math.floor(rand() * 4) }, () => Math.floor(rand() * 10));
  let text = '';
  for (let i = 0; i < length; i++) text += pool[Math.floor(rand() * pool.length)];
  return [parseInt(text, 10)];
}
